            tagline = "A school workshop turns weather observations into a practical lesson in patience and evidence.",
            parts = listOf(
                StoryPart(1, "The Silent Arrow", listOf("A weather vane on the school science block had stopped turning. Students had used it for years to discuss wind direction, but lately its arrow pointed the same way.", "The science teacher said the equipment needed inspection by the maintenance team before anyone attempted a repair.", "The class offered to research how weather vanes work and prepare an observation log.")),
                StoryPart(2, "A Page of Records", listOf("The old science cupboard held weather records from several school years.", "Some entries included wind direction, cloud cover, and rainfall, while others lacked dates or observation times.", "The class decided to create a consistent format for new records.")),
                StoryPart(3, "The Maintenance Visit", listOf("The facilities team arranged for an approved technician to inspect the vane and its mounting.", "Students watched from the designated area while the technician explained the parts and identified a worn component.", "The class recorded the explanation but did not handle the equipment.")),
                StoryPart(4, "Learning the Compass", listOf("The teacher reviewed compass directions and explained how a weather vane aligns with the wind.", "Students practised using classroom diagrams and checked their understanding against a reliable science reference.", "They learned that a single observation could be misleading if the time and conditions were not recorded.")),
                StoryPart(5, "The Repair Decision", listOf("The technician recommended replacing the worn component and checking the mounting as part of the school's maintenance plan.", "The school approved the work and scheduled it for a suitable day.", "The students prepared questions about how the vane would be tested after the repair.")),
                StoryPart(6, "A Week of Observations", listOf("After the technician completed the work, the class began a supervised observation schedule.", "Pairs recorded the direction at agreed times and included cloud conditions and any uncertainty.", "When readings differed, they checked the time stamps instead of assuming someone had made a mistake.")),
                StoryPart(7, "The Windy Afternoon", listOf("A strong breeze caused the arrow to move frequently during one observation.", "The teacher explained that the class should record what it saw rather than select a direction that looked convenient.", "Students added a note about changing conditions and discussed why repeated observations were useful.")),
                StoryPart(8, "Comparing with a Forecast", listOf("The class compared its notes with a published local weather forecast.", "They found broad similarities but learned that a school weather vane was not a substitute for professional forecasting.", "The teacher asked them to describe the limits of their small data set.")),
                StoryPart(9, "The Science Display", listOf("Students prepared a display showing how the vane worked, who maintained it, and how observations were recorded.", "The technician reviewed the equipment description, while the teacher checked the scientific explanations.", "Visitors could see both the results and the questions the class still had.")),
                StoryPart(10, "Direction and Discovery", listOf("The school adopted the observation log for future science classes and added a maintenance review date.", "The students understood that the weather vane was useful because people cared for it, recorded its readings consistently, and interpreted them cautiously.", "When the arrow turned again in the afternoon breeze, the class saw more than a moving pointer: they saw a lesson in evidence, teamwork, and patient observation."))
